// === Tab: mySketch.js ===
// Signal Ecology — Multiple Colonies
// p5.js
// Click to create new colonies.
// Nearby colonies form cross-links.

let colonies = [];
let fog = [];
let stars = [];
let crossLinks = [];

const MAX_NODES = 450;
const MAX_COLONIES = 12;
const CROSS_LINK_DISTANCE = 65;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(2, 5, 16);

  colonies.push(new Colony(width * 0.32, height * 0.5));

  for (let i = 0; i < 70; i++) {
    fog.push({
      x: random(width),
      y: random(height),
      s: random(35, 110),
      a: random(1, 9)
    });
  }

  for (let i = 0; i < 45; i++) {
    stars.push({
      x: random(width),
      y: random(height),
      s: random(1, 2.5),
      a: random(40, 240)
    });
  }
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  background(2, 5, 16, 34);

  drawAtmosphere();
  drawStars();

  for (let c of colonies) {
    c.update();
    c.display();
  }

  updateCrossLinks();
  displayCrossLinks();

  fill(220);
  noStroke();
  textFont("monospace");
  textSize(13);
  text("Signal Ecology — click to seed colonies, nearby colonies connect", 20, 30);

  let totalNodes = 0;
  let totalLinks = 0;
  for (let c of colonies) {
    totalNodes += c.nodes.length;
    totalLinks += c.links.length;
  }

  text(
    "colonies: " + colonies.length +
    "  nodes: " + totalNodes +
    "  internal links: " + totalLinks +
    "  cross links: " + crossLinks.length,
    20,
    52
  );
}

function drawAtmosphere() {
  noStroke();
  for (let f of fog) {
    fill(45, 85, 160, f.a);
    ellipse(f.x, f.y, f.s);
  }
}

function drawStars() {
  noStroke();
  for (let s of stars) {
    fill(120, 180, 255, s.a);
    circle(s.x, s.y, s.s);
  }
}

function updateCrossLinks() {
  if (frameCount % 20 !== 0) return;

  for (let i = 0; i < colonies.length; i++) {
    for (let j = i + 1; j < colonies.length; j++) {
      let a = random(colonies[i].nodes);
      let b = random(colonies[j].nodes);

      if (!a || !b) continue;

      let d = dist(a.x, a.y, b.x, b.y);

      if (d < CROSS_LINK_DISTANCE && random() < 0.35) {
        crossLinks.push(new CrossLink(a, b));
      }
    }
  }

  if (crossLinks.length > 180) {
    crossLinks.splice(0, crossLinks.length - 180);
  }
}

function displayCrossLinks() {
  for (let i = crossLinks.length - 1; i >= 0; i--) {
    let cl = crossLinks[i];
    cl.update();
    cl.display();

    if (cl.strength < 0.03) {
      crossLinks.splice(i, 1);
    }
  }
}

class Colony {
  constructor(x, y) {
    this.nodes = [];
    this.links = [];
    this.phase = "growth";

    let root = new Node(x, y);
    root.energy = 1.4;
    root.branchProbability = 0.7;
    this.nodes.push(root);
  }

  update() {
    if (frameCount % 5 === 0 && this.phase === "growth") {
      this.grow();
    }

    if (frameCount % 650 === 0) {
      this.switchPhase();
    }

    for (let n of this.nodes) n.update();
    for (let l of this.links) l.update();

    this.decay();
  }

  switchPhase() {
    this.phase = random(["growth", "growth", "stabilize", "decay"]);
  }

  grow() {
    if (this.nodes.length >= MAX_NODES) return;

    let parent = random(this.nodes);
    if (random() > parent.branchProbability) return;

    let angle =
      parent.angle +
      random(-1.1, 1.1) +
      noise(parent.x * 0.004, parent.y * 0.004, frameCount * 0.004);

    let len = random(10, 32) * parent.energy;

    let nx = parent.x + cos(angle) * len;
    let ny = parent.y + sin(angle) * len;

    if (nx < 25 || nx > width - 25 || ny < 60 || ny > height - 25) return;

    let child = new Node(nx, ny);

    child.angle = angle;
    child.energy = constrain(parent.energy + random(-0.08, 0.08), 0.25, 1.8);
    child.branchProbability = constrain(parent.branchProbability + random(-0.04, 0.04), 0.08, 0.9);
    child.communicationRadius = constrain(parent.communicationRadius + random(-6, 6), 24, 105);
    child.signalSpeed = constrain(parent.signalSpeed + random(-0.002, 0.002), 0.003, 0.026);

    this.nodes.push(child);
    this.links.push(new Link(parent, child));

    this.connectNearby(child);
  }

  connectNearby(node) {
    for (let other of this.nodes) {
      if (other === node) continue;

      var d = dist(node.x, node.y, other.x, other.y);

      if (d < node.communicationRadius && random() < 0.025) {
        this.links.push(new Link(node, other));
      }
    }
  }

  decay() {
    for (let i = this.links.length - 1; i >= 0; i--) {
      let l = this.links[i];

      if (this.phase === "decay") {
        l.strength *= 0.996;
      } else {
        l.strength *= 0.9994;
      }

      if (l.strength < 0.035) {
        this.links.splice(i, 1);
      }
    }

    for (let i = this.nodes.length - 1; i >= 0; i--) {
      let n = this.nodes[i];

      if (this.phase === "decay") {
        n.energy *= 0.996;
      } else {
        n.energy *= 0.9995;
      }

      if (n.energy < 0.04 && this.nodes.length > 1) {
        this.nodes.splice(i, 1);
      }
    }
  }

  display() {
    for (let l of this.links) l.display();
    for (let n of this.nodes) n.display();
  }
}

class Node {
  constructor(x, y) {
    this.x = x;
    this.y = y;

    this.angle = random(TWO_PI);
    this.energy = random(0.8, 1.25);
    this.branchProbability = random(0.25, 0.7);
    this.communicationRadius = random(38, 85);
    this.signalSpeed = random(0.004, 0.016);

    this.size = random(2, 4.8);
    this.pulse = random(TWO_PI);
    this.age = 0;
  }

  update() {
    this.age++;
    this.pulse += 0.04;

    let drift =
      noise(this.x * 0.003, this.y * 0.003, frameCount * 0.002) *
      TWO_PI *
      2;

    this.x += cos(drift) * 0.08;
    this.y += sin(drift) * 0.08;

    this.energy = constrain(this.energy, 0, 1.9);
    this.branchProbability = constrain(this.branchProbability, 0.04, 0.92);
  }

  display() {
    let glow = map(sin(this.pulse), -1, 1, 100, 230);

    noStroke();
    fill(120, 220, 255, glow);
    circle(this.x, this.y, this.size + sin(this.pulse) * 1.1);

    fill(255, 230, 170, 85);
    circle(this.x, this.y, 1.4);
  }
}

class Link {
  constructor(a, b) {
    this.a = a;
    this.b = b;

    this.signal = random(1);
    this.speed = (a.signalSpeed + b.signalSpeed) * 0.5;
    this.strength = random(0.35, 1.1);
    this.traffic = 0;
  }

  update() {
    this.signal += this.speed;

    if (this.signal > 1) {
      this.signal = 0;
      this.traffic++;
      this.strength += 0.0025;

      this.a.energy += 0.003;
      this.b.energy += 0.003;
    }

    this.strength = constrain(this.strength, 0, 1.8);
  }

  display() {
    var d = dist(this.a.x, this.a.y, this.b.x, this.b.y);
    let alpha = map(d, 0, 120, 145, 10);

    stroke(115, 175, 255, alpha * this.strength);
    strokeWeight(0.45 + this.strength * 0.95);
    line(this.a.x, this.a.y, this.b.x, this.b.y);

    let sx = lerp(this.a.x, this.b.x, this.signal);
    let sy = lerp(this.a.y, this.b.y, this.signal);

    noStroke();
    fill(255, 230, 170, 175);
    circle(sx, sy, 2.5);
  }
}

class CrossLink {
  constructor(a, b) {
    this.a = a;
    this.b = b;
    this.signal = random(1);
    this.speed = random(0.006, 0.018);
    this.strength = random(0.4, 1.2);
  }

  update() {
    this.signal += this.speed;

    if (this.signal > 1) {
      this.signal = 0;
      this.a.energy += 0.004;
      this.b.energy += 0.004;
      this.strength += 0.002;
    }

    this.strength *= 0.9985;
  }

  display() {
    var d = dist(this.a.x, this.a.y, this.b.x, this.b.y);

    if (d > CROSS_LINK_DISTANCE * 1.8) {
      this.strength *= 0.96;
    }

    stroke(130, 255, 230, 55 * this.strength);
    strokeWeight(0.7 + this.strength * 0.8);
    line(this.a.x, this.a.y, this.b.x, this.b.y);

    var sx = lerp(this.a.x, this.b.x, this.signal);
    var sy = lerp(this.a.y, this.b.y, this.signal);

    noStroke();
    fill(170, 255, 230, 180);
    circle(sx, sy, 3);
  }
}

function mousePressed() {
  if (colonies.length < MAX_COLONIES) {
    colonies.push(new Colony((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
  }
}

function keyPressed() {
  if (key === "r" || key === "R") {
    colonies = [];
    crossLinks = [];
    colonies.push(new Colony(width * 0.32, height * 0.5));
  }

  if (key === "s" || key === "S") {
    saveCanvas("signal-ecology-multiple-colonies", "png");
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

